use base94_simd::{
    DECIMAL_MAX_LEN as BASE94_DECIMAL_MAX_LEN, decimal_decode as base94_decimal_decode,
    decimal_encode as base94_decimal_encode, decode_into_kf as base94_decode_into,
    encode_into_kf as base94_encode_into,
};
use nextppp_core::{
    ObfuscationKey,
    crypto::ssea::{delta_encode, lcg_next, masked_xor_random_next, shuffle},
    frame::{
        base94::Base94Framer,
        binary::{PayloadFlags, header_decrypt, payload_deobfuscate},
        checksum::inet_chksum,
    },
    handshake::{SessionPacket, unpack_session_id},
};
use vectors::*;

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("valid hex"))
        .collect()
}

/// Sample buffer identical to the C++ generator: (i * 7 + 3) mod 256.
fn sample(len: usize) -> Vec<u8> {
    (0..len).map(|i| (i * 7 + 3) as u8).collect()
}

#[test]
fn lcg_matches_reference() {
    for &(seed, advanced) in LCG {
        let mut s = seed;
        for _ in 0..4 {
            let _ = lcg_next(&mut s);
        }
        assert_eq!(s, advanced, "seed {seed:#010x}");
    }
}

#[test]
fn shuffle_matches_reference() {
    for &(_size_hint, key, hex) in SHUFFLE {
        let expected = unhex(hex);
        let mut data = sample(expected.len());
        shuffle(&mut data, key);
        assert_eq!(data, expected, "key {key:#010x} len {}", expected.len());
    }
}

#[test]
fn delta_matches_reference() {
    for &(kf, hex) in DELTA {
        let expected = unhex(hex);
        let mut data = sample(expected.len());
        delta_encode(&mut data, kf);
        assert_eq!(data, expected, "kf {kf:#010x}");
    }
}

#[test]
fn masked_xor_matches_reference() {
    for &(len, kf, hex) in MASKED_XOR {
        let expected = unhex(hex);
        let mut data = sample(len as usize);
        masked_xor_random_next(&mut data, kf);
        assert_eq!(data, expected, "len {len} kf {kf:#010x}");
    }
}

#[test]
fn base94_encode_matches_reference() {
    let all: Vec<u8> = (0..=255u32).map(|i| i as u8).collect();
    for &(kf, hex) in BASE94_ENC {
        let expected = unhex(hex);
        let mut out = Vec::new();
        base94_encode_into(&mut out, &all, kf);
        assert_eq!(out, expected, "kf {kf:#010x}");
        let mut back = Vec::new();
        base94_decode_into(&mut back, &out, kf).unwrap();
        assert_eq!(back, all);
    }
}

#[test]
fn inet_chksum_matches_reference() {
    for &(data, sum) in CHKSUM {
        assert_eq!(inet_chksum(data), sum);
    }
}

#[test]
fn base94_decimal_matches_reference() {
    let mut buf = [0u8; BASE94_DECIMAL_MAX_LEN];
    for &(v, digits) in DEC94 {
        let len = base94_decimal_encode(v, &mut buf);
        assert_eq!(&buf[..len], digits.as_bytes(), "value {v}");
        assert_eq!(base94_decimal_decode(digits.as_bytes()).unwrap(), v);
    }
}

#[test]
fn base94_frame_headers_decode_to_reference_lengths() {
    // Rows are sequential: the first is the 7-byte extended header, the rest
    // are 4-byte simple headers, matching the sender state machine. The
    // payload itself is not covered by the extended checksum, so padding
    // with 'A' chars keeps the vectors decodable.
    let lens = [1usize, 5, 8648, 8649, 5000, 131_136];
    let mut framer = Base94Framer::new(154_543_927);
    for (i, &(_kf, hlen, _is_first, _m, _km, hex)) in FRAME_HDR.iter().enumerate() {
        let header = unhex(hex);
        assert_eq!(header.len(), hlen);
        let mut packet = header;
        packet.extend(std::iter::repeat_n(b'A', lens[i]));
        let decoded = framer.decode_packet(&packet).unwrap();
        assert_eq!(decoded.len(), lens[i], "frame {i}");
    }
}

#[test]
fn binary_header_decrypt_matches_reference() {
    for &(kf, len, _seed, header_kf, hex) in BIN_HDR {
        let bytes: [u8; 3] = unhex(hex).try_into().expect("3 bytes");
        let (decoded_len, decoded_kf) = header_decrypt(kf, None, &bytes).unwrap();
        assert_eq!(decoded_len, len);
        assert_eq!(decoded_kf, header_kf);
    }
}

#[test]
fn binary_payload_deobfuscate_inverts_reference() {
    let flags = PayloadFlags {
        masked: true,
        shuffle: true,
        delta: true,
    };
    for &(header_kf, kf, plain_hex, enc_hex) in BIN_PAYLOAD {
        let plain = unhex(plain_hex);
        let mut enc = unhex(enc_hex);
        payload_deobfuscate(&mut enc, &flags, header_kf, kf);
        assert_eq!(enc, plain, "header_kf {header_kf:#010x}");
    }
}

#[test]
fn session_id_packets_unpack_from_reference() {
    let key = ObfuscationKey::default();
    assert_eq!(key.kf, 154_543_927);

    let cases: &[(bool, u128)] = &[
        (true, 12345),
        (false, 0),
        (true, 54_200_000_000_000_000_000),
    ];
    for (i, &(is_real, expected_id)) in cases.iter().enumerate() {
        let packet = unhex(SESSION_ID[i].2);
        match unpack_session_id(&key, &packet).unwrap() {
            SessionPacket::Session(id) => {
                assert!(is_real, "frame {i} should not be a real packet");
                assert_eq!(id, expected_id, "frame {i}");
            },
            SessionPacket::Dummy => assert!(!is_real, "frame {i} should be dummy"),
        }
    }
}
